REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21023, 'Welcome to Rochenoire', 'Bienvenue sur Rochenoire');
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21024, 'Adventurer {},\r\n\r\nAzeroth is a vast and dangerous land, and its challenges will grow with you. As your skill increases, the creatures you face, the treasures you uncover, and the rewards you earn will rise to meet it.\r\n\r\nOnce you reach level 10, many lands, quests, and dungeons will adapt to your strength within their own limits. Follow the roads, heed the call for aid, and choose your path—the world is yours to explore.\r\n\r\nStand ready. Your journey begins now.', 'Aventurier {},\r\n\r\nAzeroth est une terre vaste et dangereuse, et ses défis grandiront avec vous. À mesure que vous gagnerez en puissance, les créatures que vous affronterez, les trésors que vous découvrirez et les récompenses que vous obtiendrez se hisseront à votre niveau.\r\n\r\nDès le niveau 10, de nombreuses régions, quêtes et instances s’adapteront à votre puissance, dans les limites qui leur sont propres. Suivez les routes, répondez aux appels à l’aide et choisissez votre voie : le monde n’attend que vous.\r\n\r\nTenez-vous prêt. Votre aventure commence maintenant.');
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21019, '{},\r\n\r\nYou have survived your first trials and shown that you are ready for greater challenges. Beyond the safety of your homeland, enemies gather and allies call for aid.\r\n\r\nGo where duty leads you. Test your strength, earn the trust of the Horde, and return with deeds worthy of remembrance.\r\n\r\nStrength and honor.\r\n\r\nThrall\r\nWarchief of the Horde', '{},\r\n\r\nVous avez surmonté vos premières épreuves et prouvé que vous étiez prêt à relever de plus grands défis. Au-delà des frontières de votre terre natale, les ennemis se rassemblent et nos alliés appellent à l’aide.\r\n\r\nAllez là où le devoir vous mène. Éprouvez votre force, gagnez la confiance de la Horde et revenez auréolé d’exploits dignes de mémoire.\r\n\r\nForce et honneur.\r\n\r\nThrall\r\nChef de guerre de la Horde');
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21020, '{},\r\n\r\nWord of your deeds has reached Stormwind. You have weathered your first trials and shown that you are ready to serve beyond the safety of your homeland.\r\n\r\nTravel where the people of the Alliance have need of you. Stand against the darkness, aid our allies, and carry the lion’s honor into every battle.\r\n\r\nFor the Alliance.\r\n\r\nVarian Wrynn\r\nKing of Stormwind', '{},\r\n\r\nLe récit de vos exploits est parvenu jusqu’à Hurlevent. Vous avez surmonté vos premières épreuves et prouvé que vous étiez prêt à servir au-delà des frontières de votre terre natale.\r\n\r\nRendez-vous là où les peuples de l’Alliance ont besoin de vous. Affrontez les ténèbres, prêtez main-forte à nos alliés et portez l’honneur du lion dans chaque bataille.\r\n\r\nPour l’Alliance.\r\n\r\nVarian Wrynn\r\nRoi de Hurlevent');
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21021, 'A Summons from the Warchief', 'Un appel du chef de guerre');
REPLACE INTO `acore_string` (`entry`, `content_default`, `locale_frFR`) VALUES (21022, 'A Summons from the King', 'Un appel du roi');
